-- PostgreSQL creator/admin processing schema. Requires prior migrations.
BEGIN;
CREATE TABLE IF NOT EXISTS creator_profiles(user_id BIGINT PRIMARY KEY REFERENCES users(id),channel_id BIGINT REFERENCES channels(id),display_name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','SUSPENDED')),applied_at TIMESTAMPTZ NOT NULL,reviewed_at TIMESTAMPTZ,reviewed_by BIGINT REFERENCES users(id),review_note TEXT);
CREATE TABLE IF NOT EXISTS upload_sessions(
 id UUID PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),video_id BIGINT NOT NULL REFERENCES videos(id),original_filename TEXT NOT NULL,declared_type TEXT NOT NULL,
 expected_bytes BIGINT NOT NULL CHECK(expected_bytes>0),received_bytes BIGINT NOT NULL DEFAULT 0,sha256 TEXT,status TEXT NOT NULL DEFAULT 'UPLOADING',attempts INT NOT NULL DEFAULT 0,
 description TEXT,rights_declaration BOOLEAN NOT NULL DEFAULT FALSE,adults_declaration BOOLEAN NOT NULL DEFAULT FALSE,consent_declaration BOOLEAN NOT NULL DEFAULT FALSE,
 processed_duration DOUBLE PRECISION,error TEXT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,reviewed_at TIMESTAMPTZ,reviewed_by BIGINT REFERENCES users(id),review_note TEXT
);
CREATE TABLE IF NOT EXISTS processing_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,upload_id UUID NOT NULL REFERENCES upload_sessions(id),state TEXT NOT NULL,message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS moderation_audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id BIGINT NOT NULL REFERENCES users(id),object_type TEXT NOT NULL,object_id TEXT NOT NULL,action TEXT NOT NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS review_evidence(upload_id UUID NOT NULL REFERENCES upload_sessions(id),kind TEXT NOT NULL CHECK(kind IN ('LICENSE','ADULTHOOD','CONSENT')),reference TEXT NOT NULL,checked_by BIGINT REFERENCES users(id),checked_at TIMESTAMPTZ,PRIMARY KEY(upload_id,kind));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),channel_id BIGINT REFERENCES channels(id),video_id BIGINT REFERENCES videos(id),type TEXT NOT NULL DEFAULT 'NEW_VIDEO',read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,UNIQUE(user_id,video_id,type));
CREATE INDEX IF NOT EXISTS ix_upload_status ON upload_sessions(status,created_at);
CREATE INDEX IF NOT EXISTS ix_upload_user ON upload_sessions(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS ix_processing_events_upload ON processing_events(upload_id,id DESC);
CREATE INDEX IF NOT EXISTS ix_notifications_user ON notifications(user_id,created_at DESC);
COMMIT;
